<template><section class="ops-panel"><div class="ops-section-title"><div><h2>{{ moneyChart?'支付与退款趋势':'出票与核销趋势' }}</h2><p>{{ moneyChart?'单位：元 · 模拟支付／退款':'单位：张 · 按实际发生日期' }}</p></div></div><p v-if="!rows?.length" class="ops-empty">暂无趋势数据</p><template v-else><div class="trend-legend"><span><i></i>{{ moneyChart?'支付金额':'出票量' }}</span><span><i class="secondary"></i>{{ moneyChart?'退款金额':'核销量' }}</span></div><div class="real-chart"><div v-for="r in rows" :key="r.day" class="real-day" :title="`${r.day}：${value(r,0)} / ${value(r,1)}`"><div class="real-bars"><span :style="{height:`${value(r,0)/max*100}%`}"></span><span class="secondary" :style="{height:`${value(r,1)/max*100}%`}"></span></div><small>{{ String(r.day).slice(5) }}</small></div></div><details><summary>查看每日明细</summary><table class="trend-table"><thead><tr><th>日期</th><th>{{ moneyChart?'支付金额':'出票量' }}</th><th>{{ moneyChart?'退款金额':'核销量' }}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.day"><td>{{ r.day }}</td><td>{{ value(r,0) }}</td><td>{{ value(r,1) }}</td></tr></tbody></table></details></template></section></template>
<script setup>
import {computed} from 'vue'
const props=defineProps({rows:Array,moneyChart:Boolean})
const value=(r,index)=>Number(r[props.moneyChart?(index?'refund':'payment'):(index?'checked':'issued')]||0)
const max=computed(()=>Math.max(1,...(props.rows||[]).flatMap(r=>[value(r,0),value(r,1)])))
</script>
<style scoped>
.real-chart{height:205px;display:flex;gap:5px;padding:18px 0 25px;background:repeating-linear-gradient(to top,transparent 0,transparent 39px,#edf1f7 40px);overflow:auto}.real-day{flex:1;min-width:12px;position:relative}.real-bars{height:100%;display:flex;align-items:flex-end;justify-content:center;gap:3px}.real-bars span{width:30%;max-width:20px;border-radius:3px 3px 0 0;background:#3975ea}.real-bars .secondary,.trend-legend .secondary{background:#34b8a0}.real-day small{position:absolute;bottom:-21px;left:50%;transform:translateX(-50%);font-size:9px;white-space:nowrap;color:#7c8ca4}.real-day:nth-child(n+9):not(:last-child) small{display:none}.trend-legend{display:flex;gap:20px;font-size:11px;color:#6f819c;margin:12px 0}.trend-legend i{display:inline-block;width:8px;height:8px;border-radius:3px;background:#3975ea;margin-right:5px}details{margin-top:15px;color:#58708f;font-size:12px}.trend-table{width:100%;border-collapse:collapse;margin-top:12px}.trend-table th,.trend-table td{padding:9px;text-align:right;border-bottom:1px solid #edf1f7}.trend-table td:first-child,.trend-table th:first-child{text-align:left}
</style>
